function perfectpixel_my_purchased_products_shortcode( $atts ) {
	if ( ! is_user_logged_in() ) {
		return '';
	}
	$atts    = shortcode_atts( array( 'limit' => 12, 'columns' => 4 ), $atts );
	$user_id = get_current_user_id();
	$key     = 'perfectpixel_my_products_' . $user_id;
	$ids     = get_transient( $key );
	if ( false === $ids ) {
		$ids = array();
		foreach ( wc_get_orders( array( 'customer_id' => $user_id, 'status' => wc_get_is_paid_statuses(), 'limit' => 100, 'orderby' => 'date', 'order' => 'DESC' ) ) as $order ) {
			foreach ( $order->get_items() as $item ) {
				$ids[] = (int) $item->get_product_id();
			}
		}
		$ids = array_values( array_unique( array_filter( $ids ) ) );
		set_transient( $key, $ids, DAY_IN_SECONDS );
	}
	$ids = array_slice( (array) $ids, 0, min( 50, max( 1, absint( $atts['limit'] ) ) ) );
	if ( ! $ids ) {
		$message = trim( '{{my_products_empty}}' );
		return '' !== $message ? '<p class="perfectpixel-no-purchases">' . esc_html( $message ) . '</p>' : '';
	}
	return do_shortcode( sprintf( '[products ids="%s" columns="%d" orderby="post__in"]', esc_attr( implode( ',', $ids ) ), min( 6, max( 1, absint( $atts['columns'] ) ) ) ) );
}

function perfectpixel_my_purchased_products_flush( $order_id, $from, $to, $order ) {
	if ( $order && $order->get_customer_id() ) {
		delete_transient( 'perfectpixel_my_products_' . $order->get_customer_id() );
	}
}
